{"type":"sim","engine":"widget","caption":"按顺序插入 3,2,1,4,5：观察 BF 失衡与旋转修复","html":"<style>
#avl-wrap{font-family:system-ui,sans-serif;max-width:640px;margin:0 auto}
#avl-canvas{display:block;width:100%;height:320px;background:var(--bg,#fafafa);border-radius:8px}
#avl-controls{display:flex;gap:8px;align-items:center;margin-top:12px;flex-wrap:wrap}
#avl-controls button{padding:6px 14px;border:1px solid var(--line,#ccc);background:var(--bg,#fff);border-radius:6px;cursor:pointer;font-size:13px}
#avl-controls button:disabled{opacity:.4;cursor:not-allowed}
#avl-controls button.primary{background:var(--accent,#2563eb);color:#fff;border-color:var(--accent,#2563eb)}
#avl-info{margin-top:10px;font-size:13px;line-height:1.6;min-height:3.2em;color:var(--ink,#1f2937)}
#avl-info code{background:#e5e7eb;padding:1px 5px;border-radius:3px;font-size:12px}
#avl-queue{display:flex;gap:6px;margin-top:8px;flex-wrap:wrap}
#avl-queue .key{display:inline-block;padding:3px 10px;border-radius:4px;border:1px solid var(--line,#ddd);font-size:13px;background:var(--bg,#fff)}
#avl-queue .key.done{background:var(--accent,#2563eb);color:#fff;border-color:var(--accent,#2563eb)}
#avl-queue .key.current{outline:2px solid var(--accent,#2563eb);outline-offset:1px}
</style>
<div id="avl-wrap">
<canvas id="avl-canvas" width="640" height="320"></canvas>
<div id="avl-controls">
<button id="btn-reset">重置</button>
<button id="btn-step" class="primary">下一步</button>
<button id="btn-auto">自动播放</button>
<span style="font-size:12px;color:#666;margin-left:auto">步进 <span id="step-num">0</span>/9</span>
</div>
<div id="avl-info">点击「下一步」开始：插入 3 作为根节点</div>
<div id="avl-queue"></div>
</div>
<script>
(function(){
const canvas=document.getElementById('avl-canvas'),ctx=canvas.getContext('2d');
const ink=getComputedStyle(document.documentElement).getPropertyValue('--ink').trim()||'#1f2937';
const accent=getComputedStyle(document.documentElement).getPropertyValue('--accent').trim()||'#2563eb';
const line=getComputedStyle(document.documentElement).getPropertyValue('--line').trim()||'#d1d5db';
const bg=getComputedStyle(document.documentElement).getPropertyValue('--bg').trim()||'#f9fafb';

let tree=null,stepIdx=0,autoTimer=null,animating=false;
const keys=[3,2,1,4,5];
const steps=[];

function height(n){return n?n.h:0;}
function bf(n){return n?height(n.l)-height(n.r):0;}
function upd(n){if(n)n.h=1+Math.max(height(n.l),height(n.r));}
function rotR(y){
  const x=y.l,T2=x.r;
  x.r=y;y.l=T2;
  upd(y);upd(x);
  return x;
}
function rotL(x){
  const y=x.r,T2=y.l;
  y.l=x;x.r=T2;
  upd(x);upd(y);
  return y;
}
function balance(n){
  upd(n);
  const b=bf(n);
  if(b>1){
    if(bf(n.l)<0)n.l=rotL(n.l);
    return rotR(n);
  }
  if(b<-1){
    if(bf(n.r)>0)n.r=rotR(n.r);
    return rotL(n);
  }
  return n;
}
function insert(n,k){
  if(!n)return{k:k,h:1,l:null,r:null};
  if(k<n.k)n.l=insert(n.l,k);
  else n.r=insert(n.r,k);
  return balance(n);
}

function clone(n){return n?{k:n.k,h:n.h,l:clone(n.l),r:clone(n.r)}:null;}
function findPath(n,k,path){
  if(!n)return;
  path.push(n);
  if(k<n.k)findPath(n.l,k,path);
  else if(k>n.k)findPath(n.r,k,path);
}
function getBF(n,k){
  if(!n)return 0;
  if(n.k===k)return bf(n);
  return k<n.k?getBF(n.l,k):getBF(n.r,k);
}

function buildSteps(){
  steps.length=0;
  let t=null;
  keys.forEach(k=>{
    const before=clone(t);
    const path=[];
    t=insert(t,k);
    findPath(t,k,path);
    const inserted=path[path.length-1];
    const b=getBF(t,k);
    let action='插入 '+k;
    let detail='节点 '+k+' 已插入';
    let rotNode=null;
    if(Math.abs(b)>1){
      rotNode=inserted;
      detail='节点 '+k+' 的 BF='+b+'，触发失衡修复';
      if(b>1){
        const childBF=getBF(t,inserted.l?inserted.l.k:null)||0;
        if(childBF<0)action='先左旋 '+inserted.l.k+'，再右旋 '+k;
        else action='右旋 '+k;
      }else{
        const childBF=getBF(t,inserted.r?inserted.r.k:null)||0;
        if(childBF>0)action='先右旋 '+inserted.r.k+'，再左旋 '+k;
        else action='左旋 '+k;
      }
    }
    steps.push({type:'insert',key:k,before:afterTree(before),after:afterTree(clone(t)),action,detail,rotNode:rotNode?rotNode.k:null});
  });
}

function afterTree(n){
  if(!n)return null;
  return{k:n.k,h:n.h,l:afterTree(n.l),r:afterTree(n.r),bf:bf(n)};
}

function layout(n,depth,xRange){
  if(!n)return[];
  const [x0,x1]=xRange;
  const x=(x0+x1)/2;
  const y=40+depth*55;
  const left=layout(n.l,depth+1,[x0,x]);
  const right=layout(n.r,depth+1,[x,x1]);
  return[{k:n.k,x,y,bf:n.bf},...left,...right];
}

function drawTree(state,highlightKey,rotKey){
  ctx.clearRect(0,0,canvas.width,canvas.height);
  if(!state)return;
  const nodes=layout(state,0,[40,600]);
  const pos={};
  nodes.forEach(n=>pos[n.k]=n);

  ctx.strokeStyle=line;
  ctx.lineWidth=1.5;
  function drawEdges(n){
    if(!n)return;
    const p=pos[n.k];
    if(n.l&&pos[n.l.k]){
      const c=pos[n.l.k];
      ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(c.x,c.y);ctx.stroke();
      drawEdges(n.l);
    }
    if(n.r&&pos[n.r.k]){
      const c=pos[n.r.k];
      ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(c.x,c.y);ctx.stroke();
      drawEdges(n.r);
    }
  }
  drawEdges(state);

  nodes.forEach(n=>{
    const isNew=n.k===highlightKey;
    const isRot=n.k===rotKey;
    ctx.beginPath();
    ctx.arc(n.x,n.y,18,0,Math.PI*2);
    ctx.fillStyle=isNew?accent:(isRot?'#dc2626':bg);
    ctx.fill();
    ctx.strokeStyle=isNew?accent:(isRot?'#dc2626':ink);
    ctx.lineWidth=isNew||isRot?2.5:1.5;
    ctx.stroke();

    ctx.fillStyle=isNew||isRot?'#fff':ink;
    ctx.font='bold 14px sans-serif';
    ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.fillText(n.k,n.x,n.y);

    ctx.fillStyle='#666';
    ctx.font='11px sans-serif';
    ctx.fillText('bf:'+n.bf,n.x,n.y+28);
  });
}

function updateUI(){
  const info=document.getElementById('avl-info');
  const queue=document.getElementById('avl-queue');
  const stepNum=document.getElementById('step-num');
  const btnStep=document.getElementById('btn-step');
  const btnAuto=document.getElementById('btn-auto');

  queue.innerHTML='';
  keys.forEach((k,i)=>{
    const span=document.createElement('span');
    span.className='key';
    span.textContent=k;
    if(i<Math.floor(stepIdx/2))span.classList.add('done');
    if(stepIdx%2===0&&i===Math.floor(stepIdx/2))span.classList.add('current');
    queue.appendChild(span);
  });

  stepNum.textContent=stepIdx;

  if(stepIdx===0){
    drawTree(null);
    info.innerHTML='点击「下一步」开始：插入 <code>3</code> 作为根节点';
    btnStep.disabled=false;btnAuto.disabled=false;
    return;
  }

  const s=steps[Math.floor((stepIdx-1)/2)];
  if(!s){btnStep.disabled=true;btnAuto.disabled=true;return;}

  const isBefore=stepIdx%2===1;
  const treeState=isBefore?s.before:s.after;
  const highlight=isBefore?s.key:null;
  const rot=isBefore?null:s.rotNode;

  drawTree(treeState,highlight,rot);

  if(isBefore){
    info.innerHTML='步骤：插入 <code>'+s.key+'</code> —— 查找空位';
  }else{
    let html='已插入 <code>'+s.key+'</code>，BF 计算完成';
    if(s.rotNode)html+='；<span style="color:#dc2626">'+s.action+'</span> 恢复平衡';
    else html+='；无需旋转';
    html+='<br><small>'+s.detail+'</small>';
    info.innerHTML=html;
  }

  if(stepIdx>=steps.length*2){
    btnStep.disabled=true;
    btnAuto.disabled=true;
    info.innerHTML+='<br><strong>完成</strong>：AVL 树已构建，所有节点 |BF|≤1';
  }
}

function step(){
  if(stepIdx>=steps.length*2)return;
  stepIdx++;
  updateUI();
}

function reset(){
  stepIdx=0;
  if(autoTimer){clearInterval(autoTimer);autoTimer=null;}
  document.getElementById('btn-auto').textContent='自动播放';
  updateUI();
}

function toggleAuto(){
  if(autoTimer){
    clearInterval(autoTimer);autoTimer=null;
    document.getElementById('btn-auto').textContent='自动播放';
  }else{
    document.getElementById('btn-auto').textContent='暂停';
    autoTimer=setInterval(()=>{
      if(stepIdx>=steps.length*2){toggleAuto();return;}
      step();
    },1200);
  }
}

buildSteps();
reset();

document.getElementById('btn-step').onclick=step;
document.getElementById('btn-reset').onclick=reset;
document.getElementById('btn-auto').onclick=toggleAuto;
})();
</script>"}
